    "id": "revisao-rjal-rjal-completo-49-mensal",
    "law": "rjal",
    "topic": "Autarquias: competências, funcionamento e prática de RH",
    "subtopic": "Sessões e reuniões",
    "familyId": "rjal:revisao-rjal-completo-49-mensal",
